import { test, expect } from '@playwright/test';

test.describe('Error Page Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/'); // Navigate to the base URL
  });

  test('should display error page on 500 server error', async ({ page }) => {
    await page.route('**/api/endpoint', (route) => {
      route.fulfill({
        status: 500,
        body: 'Internal Server Error',
      });
    });

    await page.click(getByText('Trigger 500 Error')); // Assuming there's a button to trigger the error
    await expect(page.getByRole('heading', { name: /error/i })).toBeVisible(); // Check for error heading
    await expect(page.getByText(/internal server error/i)).toBeVisible(); // Check for error message
  });

  test('should not display error page on successful response', async ({ page }) => {
    await page.route('**/api/endpoint', (route) => {
      route.fulfill({
        status: 200,
        body: JSON.stringify({ message: 'Success' }),
      });
    });

    await page.click(getByText('Trigger Success')); // Assuming there's a button to trigger success
    await expect(page.getByRole('heading', { name: /success/i })).toBeVisible(); // Check for success heading
    await expect(page.getByText(/success/i)).toBeVisible(); // Check for success message
  });
});
